	class ClassHandler<T> {
		private Set<ConfigStateField<object>> fields = new();

		ClassHandler(Class<T> cls, Lookup lookup)
    {
			gatherAnnotatedFields(cls, lookup);
		}

		private void gatherAnnotatedFields(Class<object> cls, Lookup lookup)
    {
			foreach (Field f in cls.getDeclaredFields()) {
				AutoConfigStateField annot = f.getAnnotation(typeof(AutoConfigStateField));
				if (annot == null) {
					continue;
				}
				fields.add(new(annot, f, f.getType(), lookup));
			}
		}

		public void writeConfigState(T from, SaveState into) {
			foreach (ConfigStateField<object> f in fields) {
				f.save(from, into);
			}
		}

		public void readConfigState(T into, SaveState from) {
			foreach (ConfigStateField<object> f in fields) {
				f.load(into, from);
			}
		}
	}

